from pathlib import Path
from html import escape
import json

root = Path(__file__).resolve().parents[1]
items = [
    ('01-ordinary-week', 'Tuesday got away. Wednesday is still here.', 'For the interrupted week', 'A purpose-drawn calendar in the poster’s colours, with room for the gaps in an ordinary week.'),
    ('02-give-it-a-when', 'Give your habit a when.', 'For a concrete starting point', 'A clear when–then example turns an intention into a concrete plan.'),
    ('03-ordinary-tuesday', 'Researchers are interested in your ordinary Tuesday.', 'For the research invitation', 'Everyday language makes the research purpose personal and easy to understand.'),
]
posts, articles = {}, []
for stem, title, role, description in items:
    for lang in ('en', 'de'):
        posts[stem+'-'+lang] = (root/'copy'/f'{stem}-{lang}.txt').read_text().strip()
    articles.append(f'''<article id="{stem}"><a class="art" href="images/{stem}.png" target="_blank"><img src="images/{stem}.png" alt="{escape(title)} Health Habit Hub poster" width="1080" height="1350"></a><div class="details"><h2>{escape(title)}</h2><p class="intent">{description}</p><a class="download" href="images/{stem}.png" download>Download this image</a><div class="post-controls"><div class="languages" aria-label="Post language"><button data-stem="{stem}" data-lang="en" aria-pressed="true">English</button><button data-stem="{stem}" data-lang="de" aria-pressed="false">Deutsch</button></div><button class="copy" data-copy="{stem}">Copy post</button></div><textarea id="post-{stem}" aria-label="{escape(title)} LinkedIn text" readonly>{escape(posts[stem+'-en'])}</textarea><a id="text-{stem}" class="text-download" href="copy/{stem}-en.txt" download>Download post text</a></div></article>''')

html = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Health Habit Hub · Ordinary days campaign</title><style>
@font-face{font-family:Barlow;src:url(fonts/BarlowCondensed-ExtraBold.ttf);font-weight:800;font-display:swap}@font-face{font-family:Figtree;src:url(fonts/Figtree-Regular.ttf);font-weight:400;font-display:swap}@font-face{font-family:Figtree;src:url(fonts/Figtree-Bold.ttf);font-weight:700;font-display:swap}
:root{color-scheme:light;--ink:#172126;--ground:#eef1eb;--paper:#f5f7f2;--green:#2e8c00;--line:#b9c3b7}*{box-sizing:border-box}html{scrollbar-color:#68796b var(--ground)}body{margin:0;background:var(--ground);color:var(--ink);font-family:Figtree,Arial,sans-serif}::selection{background:#c7f07a;color:var(--ink)}a{color:inherit;text-underline-offset:4px}button,textarea{font:inherit}button{cursor:pointer}a:focus-visible,button:focus-visible,textarea:focus-visible{outline:3px solid var(--green);outline-offset:5px}.wrap{max-width:1580px;margin:auto;padding:0 4vw}header{display:flex;justify-content:space-between;align-items:center;gap:20px;padding-top:26px;padding-bottom:22px;border-bottom:1px solid var(--line)}.wordmark{font-weight:700;letter-spacing:-.025em;font-size:20px}nav{display:flex;gap:24px;font-size:13px}.intro{padding:30px 0 34px;display:flex;gap:30px;justify-content:space-between;align-items:end}h1{font-size:36px;font-weight:700;letter-spacing:-.035em;margin:0;line-height:1.1;max-width:520px}.intro p{max-width:410px;margin:0;color:#4d5d50;font-size:14px;line-height:1.5}.campaigns{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.art{display:block;overflow:hidden}.art img{display:block;width:100%;height:auto}.details{padding-top:22px}h2{font-size:25px;letter-spacing:-.025em;line-height:1.15;margin:0 0 12px;font-weight:700}.intent{font-size:14px;line-height:1.55;color:#4d5d50;min-height:46px;margin:0 0 17px}.download{display:inline-flex;gap:16px;align-items:center;border-bottom:1px solid var(--ink);padding-bottom:4px;text-decoration:none;font-size:14px;font-weight:700}.download:hover{color:var(--green)}.post-controls{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:30px;padding-top:20px;border-top:1px solid var(--line)}.languages{display:flex;gap:14px}.languages button{border:0;border-bottom:2px solid transparent;background:none;color:#526255;padding:5px 0;font-size:12px}.languages button[aria-pressed=true]{color:var(--ink);border-color:var(--ink);font-weight:700}.copy{background:var(--ink);color:var(--paper);padding:9px 12px;border:1px solid var(--ink);font-size:12px}.copy:hover{background:#304a36}.copy:active{transform:translateY(1px)}textarea{display:block;width:100%;min-height:335px;resize:vertical;margin-top:14px;padding:15px;background:var(--paper);color:var(--ink);border:1px solid #d1d9cd;font-size:14px;line-height:1.6;caret-color:var(--green)}.text-download{display:inline-block;margin-top:10px;font-size:12px;color:#3f5843}.motion{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:50px;padding:60px 0 45px;margin-top:60px;border-top:1px solid var(--line);align-items:center}.motion video{width:100%;max-height:580px;background:var(--ink);display:block;object-fit:contain}.motion h2{font-size:38px;max-width:480px}.motion p{line-height:1.65;font-size:17px;max-width:470px}.motion .small{font-size:13px;color:#4d5d50;max-width:450px}.links{display:flex;gap:20px;flex-wrap:wrap;margin-top:25px;font-size:14px}footer{padding:26px 0 40px;border-top:1px solid var(--line);font-size:12px;color:#526255;display:flex;justify-content:space-between;gap:20px}.notice{font-size:13px;color:#526255;line-height:1.6;margin:26px 0 0}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.changed{animation:change .18s ease-out}@keyframes change{from{opacity:.45}to{opacity:1}}@media(prefers-reduced-motion:reduce){.changed{animation:none}}@media(max-width:980px){.campaigns{grid-template-columns:1fr}.campaigns article{display:grid;grid-template-columns:1fr 1fr;gap:25px}.details{padding:0}h2{font-size:29px}.intro{display:block}.intro p{margin-top:18px;max-width:550px}.intent{min-height:0}.post-controls{margin-top:23px}textarea{min-height:320px}.motion{gap:30px}.motion h2{font-size:31px}}@media(max-width:620px){.wrap{padding-left:5vw;padding-right:5vw}header{padding-top:22px}.wordmark{font-size:17px}nav{gap:14px;font-size:12px}nav a:last-child{display:none}.intro{padding:28px 0}h1{font-size:30px}.campaigns{gap:45px}.campaigns article{display:block}.details{padding-top:20px}h2{font-size:25px}.intent{margin-bottom:17px}textarea{min-height:300px}.motion{grid-template-columns:1fr;margin-top:45px;padding-top:35px;gap:26px}.motion video{max-height:560px}.motion h2{font-size:30px}.motion p{font-size:16px}footer{display:block}footer span{display:block;margin-top:12px}}
</style></head><body><header class="wrap"><div class="wordmark">Health Habit Hub</div><nav><a href="copy/linkedin-posts.md">All post text</a><a href="README.md">Asset guide</a></nav></header><main class="wrap"><div class="intro"><h1>Habits live in ordinary days.</h1><p>Three picture campaigns with bold typography, clear habit illustrations and matching English and German post text.</p></div><section class="campaigns" aria-label="Revised campaign artwork">''' + '\n'.join(articles) + '''</section><section class="motion" aria-label="New motion post"><video controls playsinline preload="metadata" poster="video/preview-01-hook.png"><source src="video/01-give-it-a-when.mp4" type="video/mp4"></video><div><h2>A habit with a “when.”<br>In 18 seconds.</h2><p>The new motion post brings the planning idea to life, shows the actual app and invites a free download.</p><p class="small">Silent, with readable on-screen copy. Uses genuine phone footage originally rendered in PromoStudio. The same specific voice carries through from the posters.</p><div class="links"><a class="download" href="video/01-give-it-a-when.mp4" download>Download video</a><a href="copy/02-give-it-a-when-en.txt" download>Matching post text</a></div></div></section><p class="notice">The calendar and habit-plan graphics are illustrations, not app screenshots or participant records. The video uses genuine app footage. The earlier campaign remains available separately.</p></main><footer class="wrap"><a href="https://healthhabithub.de/">healthhabithub.de</a><span>English artwork and video · English / German post copy · Polished 1 November 2026</span></footer><div id="status" class="sr-only" aria-live="polite"></div><script>const posts=POSTS_DATA;document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{const stem=b.dataset.stem,lang=b.dataset.lang,t=document.getElementById('post-'+stem);t.value=posts[stem+'-'+lang];t.classList.remove('changed');void t.offsetWidth;t.classList.add('changed');b.parentElement.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));document.getElementById('text-'+stem).href='copy/'+stem+'-'+lang+'.txt'}));document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{const t=document.getElementById('post-'+b.dataset.copy);try{await navigator.clipboard.writeText(t.value);b.textContent='Copied';document.getElementById('status').textContent='Post copied';setTimeout(()=>b.textContent='Copy post',1800)}catch(e){t.focus();t.select();b.textContent='Text selected';document.getElementById('status').textContent='Text selected. Use your usual copy shortcut.'}}));</script></body></html>'''
html = html.replace('POSTS_DATA', json.dumps(posts, ensure_ascii=False).replace('</', '<\\/'))
(root/'index.html').write_text(html)
print(root/'index.html')
